-- Chạy 1 lần để đưa 6 tin hiện tại vào bảng jobs.
on conflict (slug) do update set
  company_name=excluded.company_name,location=excluded.location,job_title=excluded.job_title,salary=excluded.salary,shift=excluded.shift,age_requirement=excluded.age_requirement,gender_requirement=excluded.gender_requirement,description=excluded.description,requirements=excluded.requirements,benefits=excluded.benefits,hr_name=excluded.hr_name,hr_phone=excluded.hr_phone,hr_zalo=excluded.hr_zalo,image_url=excluded.image_url,is_active=excluded.is_active,is_urgent=excluded.is_urgent,updated_at=now();
